//! Native instruction entries refer to the installed link, so source updates
//! and library migration keep working without copying local adaptation text.
use std::{fs, io::{Read, Write}, path::{Path, PathBuf}};
use anyhow::{Context, Result, ensure};
use sha2::{Digest, Sha256};
use crate::{InstallTarget, package_fs::Directory};

mod jsonc;
mod opencode;
mod pi;
mod hermes;
mod hermes_yaml;
mod openclaw_json;
mod openclaw;
mod trae;
mod antigravity;
mod agents_md;
mod workbuddy;
mod grok;
use crate::file_access as permissions;

// Stable generated bytes with and without serde_json/preserve_order.
fn canonical_json(mut value: serde_json::Value) -> Result<String> {
    value.sort_all_objects();
    Ok(serde_json::to_string(&value)?)
}

#[derive(Clone, Debug)]
struct ManagedFileRule {
    pub(crate) path: PathBuf,
    logical: PathBuf,
    anchor: PathBuf,
    anchor_identity: String,
    rules_identity: Option<String>,
    body: Vec<u8>,
    expected: Option<(Vec<u8>, String)>,
    max_bytes: u64,
    source_guard: Option<(PathBuf, String)>,
    installation_guard: Option<(PathBuf, Option<String>)>,
    rollback_body: Option<Vec<u8>>,
    removal_source_guard: Option<(PathBuf, String)>,
    source_installation: Option<PathBuf>,
}

#[derive(Clone, Debug)]
pub(crate) struct RulePlan {
    pub(crate) path: PathBuf,
    kind: RuleKind,
}

#[derive(Clone, Debug)]
enum RuleKind { File(ManagedFileRule), OpenCode(opencode::ConfigPlan), Hermes(hermes::Plan), OpenClaw(openclaw::Plan) }

#[derive(Default)]
pub(crate) struct RulePool { opencode: opencode::Pool, profile_files: hermes::Pool }

impl RulePlan {
    pub(crate) fn for_target(target: InstallTarget, installation: &Path) -> Result<Option<Self>> {
        if target == InstallTarget::OpenClaw {
            return openclaw::existing(installation).map(|plan| plan.map(|plan| Self { path: plan.path.clone(), kind: RuleKind::OpenClaw(plan) }));
        }
        if target == InstallTarget::Hermes {
            return hermes::existing(installation).map(|plan| plan.map(|plan| Self { path: plan.path.clone(), kind: RuleKind::Hermes(plan) }));
        }
        if target == InstallTarget::OpenCode {
            let plan = opencode::ConfigPlan::new(installation)?;
            return Ok(Some(Self { path: plan.path.clone(), kind: RuleKind::OpenCode(plan) }));
        }
        if target == InstallTarget::Droid {
            let plan = opencode::ConfigPlan::new_droid(installation)?;
            return Ok(Some(Self { path: plan.path.clone(), kind: RuleKind::OpenCode(plan) }));
        }
        if matches!(target, InstallTarget::Pi | InstallTarget::Omp) {
            return pi::existing_for(target, installation);
        }
        Ok(ManagedFileRule::for_target(target, installation)?.map(|plan| Self {
            path: plan.path.clone(), kind: RuleKind::File(plan),
        }))
    }

    pub(crate) fn for_install(target: InstallTarget, installation: &Path, source: &Path) -> Result<Option<Self>> {
        if target == InstallTarget::OpenClaw { return Self::openclaw_plan(None, installation, source, true).map(Some); }
        if target == InstallTarget::Hermes { return Self::for_hermes(installation, source, true).map(Some); }
        if matches!(target, InstallTarget::Pi | InstallTarget::Omp) {
            return pi::plan_for(target, installation, source).map(Some);
        }
        Self::for_target(target, installation)
    }

    pub(crate) fn for_hermes(installation: &Path, source: &Path, install: bool) -> Result<Self> {
        let plan = hermes::plan(installation, source, install)?;
        Ok(Self { path: plan.path.clone(), kind: RuleKind::Hermes(plan) })
    }

    pub(crate) fn for_openclaw(project: &Path, installation: &Path, source: &Path, install: bool) -> Result<Self> {
        Self::openclaw_plan(Some(project), installation, source, install)
    }

    fn openclaw_plan(project: Option<&Path>, installation: &Path, source: &Path, install: bool) -> Result<Self> {
        let plan = openclaw::plan(project, installation, source, install)?;
        Ok(Self { path: plan.path.clone(), kind: RuleKind::OpenClaw(plan) })
    }

    pub(crate) fn paths(&self) -> Vec<PathBuf> {
        match &self.kind { RuleKind::Hermes(plan) => plan.paths(), RuleKind::OpenClaw(plan) => plan.paths(), _ => vec![self.path.clone()] }
    }

    pub(crate) fn for_omp(project: &Path, installation: &Path, source: &Path) -> Result<Self> {
        let skills = crate::agents::installation_root(project, InstallTarget::Omp)?;
        pi::plan_at(InstallTarget::Omp, installation, source,
            Some(skills.parent().context("缺少 OMP 配置目录")?))
    }

    pub(crate) fn for_trae(project: &Path, installation: &Path) -> Result<Self> {
        Self::for_file_host(project, InstallTarget::Trae, installation)
    }

    pub(crate) fn is_file_host(target: InstallTarget) -> bool {
        matches!(target, InstallTarget::Trae | InstallTarget::Antigravity | InstallTarget::WorkBuddy | InstallTarget::Grok)
    }

    pub(crate) fn for_file_host(project: &Path, host: InstallTarget, installation: &Path) -> Result<Self> {
        if host == InstallTarget::WorkBuddy {
            // Desktop rules have a different project root from native skills.
            let home = dirs::home_dir().context("无法取得 WorkBuddy 用户目录")?;
            let rules = if crate::project_discovery::path_identity(&home)
                == crate::project_discovery::path_identity(project) {
                crate::agents::workbuddy_config_root(&home)?.join("rules")
            } else { project.join(".codebuddy/rules") };
            let plan = workbuddy::plan_at(&rules, installation)?;
            return Ok(Self { path: plan.path.clone(), kind: RuleKind::File(plan) });
        }
        let skills = crate::agents::installation_root(project, host)?;
        let config = skills.parent().context("缺少原生配置目录")?;
        let plan = match host {
            InstallTarget::Trae => trae::plan(config, installation)?,
            InstallTarget::Antigravity => antigravity::plan(config, installation)?,
            InstallTarget::Grok => grok::plan(config, installation)?,
            _ => anyhow::bail!("不支持此文件规则宿主"),
        };
        Ok(Self { path: plan.path.clone(), kind: RuleKind::File(plan) })
    }

    pub(crate) fn for_trae_if_affected(project: &Path, installation: &Path) -> Result<Option<Self>> {
        if !trae::affected(project, installation)? { return Ok(None); }
        Self::for_trae(project, installation).map(Some)
    }

    pub(crate) fn trae_removals(project: &Path, installation: &Path) -> Result<Vec<Self>> {
        Self::file_host_removals_for(project, InstallTarget::Trae, installation)
    }

    pub(crate) fn grok_hooks_for_install(project: &Path, installation: &Path, source: &Path) -> Result<Vec<Self>> {
        let skills = crate::agents::installation_root(project, InstallTarget::Grok)?;
        grok::hook_install(skills.parent().context("缺少 Grok 配置目录")?, installation, source)
    }

    pub(crate) fn for_file_hosts_if_affected(project: &Path, installation: &Path, source: &Path) -> Result<Vec<Self>> {
        let mut plans = Vec::new();
        for host in [InstallTarget::Trae, InstallTarget::Antigravity, InstallTarget::WorkBuddy, InstallTarget::Grok] {
            if file_host_affected(project, host, installation)? {
                plans.push(Self::for_file_host(project, host, installation)?);
                if host == InstallTarget::Grok {
                    plans.extend(Self::grok_hooks_for_install(project, installation, source)?);
                }
            }
        }
        if copilot_affected(project, installation)? {
            plans.push(Self::for_copilot(project, installation)?);
        }
        Self::merge_all(plans)
    }

    pub(crate) fn file_host_removals(project: &Path, installation: &Path) -> Result<Vec<Self>> {
        let mut plans = Vec::new();
        for host in [InstallTarget::Trae, InstallTarget::Antigravity, InstallTarget::WorkBuddy, InstallTarget::Grok] {
            plans.extend(Self::file_host_removals_for(project, host, installation)?);
        }
        plans.extend(Self::copilot_removals(project, installation)?);
        Self::merge_all(plans)
    }

    pub(crate) fn file_host_removals_for(project: &Path, host: InstallTarget, installation: &Path) -> Result<Vec<Self>> {
        if !file_host_affected(project, host, installation)? { return Ok(Vec::new()); }
        let mut plans = Vec::new();
        for path in installation_aliases(project, installation)? {
            let expected = match fs::symlink_metadata(&path) {
                Ok(_) => Some(crate::library::filesystem_identity(&path)?),
                Err(error) if error.kind() == std::io::ErrorKind::NotFound => None,
                Err(error) => return Err(error.into()),
            };
            if host == InstallTarget::Grok {
                let skills = crate::agents::installation_root(project, host)?;
                let mut hooks = grok::hook_removals(skills.parent().context("缺少 Grok 配置目录")?, &path)?;
                for hook in &mut hooks {
                    if let RuleKind::File(rule) = &mut hook.kind {
                        rule.installation_guard = Some((path.clone(), expected.clone()));
                    }
                }
                plans.extend(hooks);
            }
            let mut plan = Self::for_file_host(project, host, &path)?;
            if let RuleKind::File(rule) = &mut plan.kind {
                rule.installation_guard = Some((path, expected));
            }
            plans.push(plan);
        }
        Self::merge_all(plans)
    }

    pub(crate) fn for_pi(project: &Path, installation: &Path, source: &Path) -> Result<Self> {
        let skills = crate::agents::installation_root(project, InstallTarget::Pi)?;
        pi::plan_at(InstallTarget::Pi, installation, source,
            Some(skills.parent().context("缺少 Pi 配置目录")?))
    }

    /// OpenCode also consumes native compatibility roots such as .claude.
    /// Its configuration belongs to OpenCode while its import uses the actual link.
    pub(crate) fn for_opencode(project: &Path, installation: &Path) -> Result<Self> {
        let skills = crate::agents::installation_root(project, InstallTarget::OpenCode)?;
        let plan = opencode::ConfigPlan::new_at(skills.parent().context("缺少 OpenCode 配置目录")?, installation)?;
        Ok(Self { path: plan.path.clone(), kind: RuleKind::OpenCode(plan) })
    }

    pub(crate) fn for_copilot(project: &Path, installation: &Path) -> Result<Self> {
        let skills = crate::agents::installation_root(project, InstallTarget::Copilot)?;
        let plan = opencode::ConfigPlan::new_copilot_at(
            skills.parent().context("缺少 Copilot 配置目录")?, installation)?;
        Ok(Self { path: plan.path.clone(), kind: RuleKind::OpenCode(plan) })
    }

    pub(crate) fn copilot_removals(project: &Path, installation: &Path) -> Result<Vec<Self>> {
        if !copilot_affected(project, installation)? { return Ok(Vec::new()); }
        let aliases = installation_aliases(project, installation)?;
        aliases.iter().map(|path| {
            let mut plan = Self::for_copilot(project, path)?;
            if let RuleKind::OpenCode(config) = &mut plan.kind { config.guard_copilot_removal(&aliases)?; }
            Ok(plan)
        }).collect()
    }

    pub(crate) fn merge(&mut self, other: Self) -> Result<()> {
        ensure!(self.path == other.path, "不能合并不同原生适配入口");
        match (&mut self.kind, other.kind) {
            (RuleKind::OpenCode(a), RuleKind::OpenCode(b)) => a.merge(b),
            (RuleKind::Hermes(a), RuleKind::Hermes(b)) => a.merge(b),
            (RuleKind::OpenClaw(a), RuleKind::OpenClaw(b)) => a.merge(b),
            (RuleKind::File(a), RuleKind::File(b)) => {
                ensure!(a.body == b.body && a.expected == b.expected
                    && a.installation_guard == b.installation_guard && a.source_guard == b.source_guard
                    && a.removal_source_guard == b.removal_source_guard && a.source_installation == b.source_installation, "同一原生规则入口内容冲突，已保留");
                Ok(())
            }
            _ => anyhow::bail!("同一原生入口涉及不同配置类型，已保留"),
        }
    }

    pub(crate) fn merge_all(mut plans: Vec<Self>) -> Result<Vec<Self>> {
        plans.sort_by(|a, b| a.path.cmp(&b.path));
        let mut merged: Vec<Self> = Vec::new();
        for plan in plans {
            if let Some(previous) = merged.last_mut().filter(|previous| previous.path == plan.path) {
                previous.merge(plan)?;
            } else { merged.push(plan); }
        }
        Ok(merged)
    }

    pub(crate) fn coalesce(&mut self, pool: &mut RulePool) -> Result<()> {
        match &mut self.kind {
            RuleKind::OpenCode(plan) => plan.coalesce(&mut pool.opencode),
            RuleKind::Hermes(plan) => plan.coalesce(&mut pool.profile_files, &mut pool.opencode),
            RuleKind::OpenClaw(plan) => plan.coalesce(&mut pool.profile_files, &mut pool.opencode),
            RuleKind::File(_) => Ok(()),
        }
    }
    pub(crate) fn binds_installation(&self) -> bool {
        matches!(&self.kind, RuleKind::File(plan) if plan.source_installation.is_some())
    }
    pub(crate) fn needs_install(&self) -> bool {
        match &self.kind { RuleKind::File(p) => p.needs_install(), RuleKind::OpenCode(p) => p.needs_install(), RuleKind::Hermes(p) => p.needs_install(), RuleKind::OpenClaw(p) => p.needs_install() }
    }
    pub(crate) fn validate(&self) -> Result<()> {
        match &self.kind { RuleKind::File(p) => p.validate(), RuleKind::OpenCode(p) => p.validate(), RuleKind::Hermes(p) => p.validate(), RuleKind::OpenClaw(p) => p.validate() }
    }
    pub(crate) fn install(&mut self) -> Result<bool> {
        match &mut self.kind { RuleKind::File(p) => p.install(), RuleKind::OpenCode(p) => p.install(), RuleKind::Hermes(p) => p.install(), RuleKind::OpenClaw(p) => p.install() }
    }
    pub(crate) fn detach(&mut self) -> Result<bool> {
        match &mut self.kind { RuleKind::File(p) => p.detach(), RuleKind::OpenCode(p) => p.detach(), RuleKind::Hermes(p) => p.detach(), RuleKind::OpenClaw(p) => p.detach() }
    }
    pub(crate) fn rollback_install(&mut self) -> Result<bool> {
        match &mut self.kind { RuleKind::OpenCode(p) => p.rollback_install(), RuleKind::File(p) => p.rollback_install(), _ => self.detach() }
    }
}

// A scan may return a different logical root for the same physical slot.
// Retire only known aliases of that slot, never other links to the same source.
fn installation_aliases(project: &Path, installation: &Path) -> Result<Vec<PathBuf>> {
    let name = installation.file_name().context("缺少技能名称")?;
    let physical = crate::cross_project::physical_entry(installation)?;
    let mut paths = vec![installation.to_path_buf()];
    for target in crate::agents::PROJECT_INSTALL_TARGETS.iter().filter(|target| **target != InstallTarget::Proma) {
        let Ok(root) = crate::agents::installation_root(project, *target) else { continue; };
        let candidate = root.join(name);
        if crate::cross_project::physical_entry(&candidate)? == physical && !paths.contains(&candidate) {
            paths.push(candidate);
        }
    }
    Ok(paths)
}

fn copilot_affected(project: &Path, installation: &Path) -> Result<bool> {
    let name = installation.file_name().context("缺少技能名称")?;
    let home = dirs::home_dir().context("无法取得 Copilot 用户目录")?;
    let global = crate::project_discovery::path_identity(&home)
        == crate::project_discovery::path_identity(project);
    let mut targets = vec![InstallTarget::Copilot];
    // Nondefault COPILOT_HOME excludes the default personal .agents root.
    if !global || crate::agents::copilot_config_selection(&home)?.1 {
        targets.push(InstallTarget::Universal);
    }
    if !global { targets.push(InstallTarget::ClaudeCode); }
    let physical = crate::cross_project::physical_entry(installation)?;
    for target in targets {
        let candidate = crate::agents::installation_root(project, target)?.join(name);
        if crate::cross_project::physical_entry(&candidate)? == physical { return Ok(true); }
    }
    Ok(false)
}

fn file_host_affected(project: &Path, host: InstallTarget, installation: &Path) -> Result<bool> {
    if host == InstallTarget::Trae { return trae::affected(project, installation); }
    if host == InstallTarget::Grok {
        let Some(name) = installation.file_name() else { return Ok(false); };
        let physical = crate::cross_project::physical_entry(installation)?;
        for target in [InstallTarget::Grok, InstallTarget::Universal, InstallTarget::ClaudeCode, InstallTarget::Cursor] {
            let candidate = crate::agents::installation_root(project, target)?.join(name);
            if crate::cross_project::physical_entry(&candidate)? == physical { return Ok(true); }
        }
        return Ok(false);
    }
    ensure!(matches!(host, InstallTarget::Antigravity | InstallTarget::WorkBuddy), "不支持此文件规则宿主");
    let Some(name) = installation.file_name() else { return Ok(false); };
    let physical = crate::cross_project::physical_entry(installation)?;
    let global = dirs::home_dir().is_some_and(|home|
        crate::project_discovery::path_identity(&home) == crate::project_discovery::path_identity(project));
    // The fixed IDE guide names .agents as a project compatibility root, but
    // its user-level root is .gemini/config. Do not infer a global shared root.
    for target in [Some(host), (host == InstallTarget::Antigravity && !global).then_some(InstallTarget::Universal)].into_iter().flatten() {
        let candidate = crate::agents::installation_root(project, target)?.join(name);
        if crate::cross_project::physical_entry(&candidate)? == physical { return Ok(true); }
    }
    Ok(false)
}

fn directory(path: &Path) -> Result<Directory> {
    #[cfg(unix)]
    { Directory::open_anchored(path) }
    #[cfg(not(unix))]
    { Directory::open(path) }
}

fn snapshot(path: &Path, max_bytes: u64) -> Result<Option<(Vec<u8>, String)>> {
    let metadata = match path.symlink_metadata() {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
        Err(error) => return Err(error.into()),
    };
    ensure!(metadata.is_file() && !metadata.file_type().is_symlink(), "原生适配入口不是普通文件，已保留");
    let parent = directory(path.parent().context("适配入口缺少父目录")?)?;
    let mut bytes = Vec::new();
    parent.read(Path::new(path.file_name().context("适配入口缺少名称")?))?.take(max_bytes + 1).read_to_end(&mut bytes)?;
    ensure!(bytes.len() as u64 <= max_bytes, "原生适配入口过大，已保留");
    Ok(Some((bytes, crate::library::filesystem_identity(path)?)))
}

fn normalize_file_rule_paths(config: &Path, installation: &Path) -> Result<(PathBuf, PathBuf)> {
    ensure!(installation.is_absolute() || !config.is_absolute(),
        "相对安装路径缺少一致的项目基准");
    let base = config.parent().context("缺少原生配置父目录")?;
    let absolute_base = std::path::absolute(base)?;
    // Resolve only the config parent. A fresh global config may have missing
    // parents; the same anchored publication still creates and guards them.
    let config = crate::cross_project::physical_entry(&std::path::absolute(config)?)?;
    let normalized_base = config.parent().context("缺少原生配置父目录")?;
    let absolute_installation = std::path::absolute(installation)?;
    let installation = absolute_installation.strip_prefix(&absolute_base)
        .map(|relative| normalized_base.join(relative))
        .unwrap_or(absolute_installation.clone());
    Ok((config, installation))
}

impl ManagedFileRule {
    pub(crate) fn for_target(target: InstallTarget, installation: &Path) -> Result<Option<Self>> {
        // WorkBuddy requires explicit project context; its skill folder does
        // not identify the desktop's independent .codebuddy/rules root.
        if target == InstallTarget::WorkBuddy { return Ok(None); }
        if RulePlan::is_file_host(target) {
            let config = installation.parent().and_then(Path::parent).context("缺少原生配置目录")?;
            return match target {
                InstallTarget::Trae => trae::plan(config, installation).map(Some),
                InstallTarget::Antigravity => antigravity::plan(config, installation).map(Some),
                InstallTarget::Grok => grok::plan(config, installation).map(Some),
                _ => unreachable!(),
            };
        }
        if target != InstallTarget::ClaudeCode { return Ok(None); }
        let name = installation.file_name().and_then(|n| n.to_str()).context("技能名称编码无效")?;
        crate::library::validate_name(name)?;
        ensure!(!name.chars().any(char::is_control), "原生适配入口不支持控制字符名称");
        let config = installation.parent().and_then(Path::parent).context("缺少 Claude 配置目录")?;
        let digest = format!("{:x}", Sha256::digest(name.as_bytes()));
        let logical = config.join("rules").join(format!("pleat-adaptation-{}.md", &digest[..24]));
        let path = crate::cross_project::physical_entry(&logical)?;
        let escaped = name.replace(' ', "\\ ");
        let body = format!("<!-- Pleat managed adaptation import v1 -->\n@../skills/{escaped}/local-data/ADAPTATION.md\n").into_bytes();
        Self::new(logical, path, body, 8192).map(Some)
    }

    fn new(logical: PathBuf, path: PathBuf, body: Vec<u8>, max_bytes: u64) -> Result<Self> {
        ensure!(body.len() as u64 <= max_bytes, "受管原生适配入口超过大小上限");
        let expected = snapshot(&path, max_bytes)?;
        ensure!(expected.as_ref().is_none_or(|(bytes, _)| bytes == &body),
            "原生适配入口已有其他内容，已保留：{}", path.display());
        let rules_identity = path.parent().filter(|parent| parent.exists())
            .map(crate::library::filesystem_identity).transpose()?;
        let mut anchor = path.parent().and_then(Path::parent).context("缺少配置目录")?;
        while !anchor.exists() { anchor = anchor.parent().context("缺少配置目录")?; }
        let anchor_identity = crate::library::filesystem_identity(anchor)?;
        Ok(Self { anchor: anchor.to_path_buf(), anchor_identity, rules_identity, path, logical, body, expected, max_bytes, source_guard: None, installation_guard: None, rollback_body: None, removal_source_guard: None, source_installation: None })
    }

    pub(crate) fn needs_install(&self) -> bool { self.expected.as_ref().is_none_or(|(bytes, _)| bytes != &self.body) }

    pub(crate) fn validate(&self) -> Result<()> {
        ensure!(crate::library::filesystem_identity(&self.anchor)? == self.anchor_identity
            && crate::cross_project::physical_entry(&self.logical)? == self.path,
            "原生适配目录身份已变化，请重新预览");
        ensure!(snapshot(&self.path, self.max_bytes)? == self.expected, "原生适配入口与预览不一致，已保留");
        if let Some((source, expected)) = &self.source_guard {
            ensure!(source.canonicalize()? == *source && crate::library::filesystem_identity(source)? == *expected, "技能源目录身份已变化，请重新预览");
            if let Some(installation) = &self.source_installation {
                match installation.symlink_metadata() {
                    Ok(_) => ensure!(installation.canonicalize().ok().as_ref() == Some(source), "Grok Hook 安装入口与技能源不一致，已保留"),
                    Err(error) if error.kind() == std::io::ErrorKind::NotFound => {},
                    Err(_) => anyhow::bail!("Grok Hook 安装入口不可验证，已保留"),
                }
            }
        }
        if let Some((installation, expected)) = &self.removal_source_guard {
            // Ownership is the exact template plus known slot. An unavailable
            // source does not prevent removal; a readable different inode does.
            if let Ok(source) = installation.canonicalize() {
                ensure!(source.is_dir() && crate::library::filesystem_identity(&source)? == *expected,
                    "Grok Hook 归属或内容冲突，已保留");
            }
        }
        if let Some((path, expected)) = &self.installation_guard {
            let actual = match fs::symlink_metadata(path) {
                Ok(_) => Some(crate::library::filesystem_identity(path)?),
                Err(error) if error.kind() == std::io::ErrorKind::NotFound => None,
                Err(error) => return Err(error.into()),
            };
            ensure!(&actual == expected, "技能安装入口身份已变化，已保留原生规则");
        }
        Ok(())
    }

    fn parent(&self) -> Result<(Directory, Directory)> {
        let parent = self.path.parent().context("缺少适配目录")?;
        let config = parent.parent().context("缺少配置目录")?;
        #[cfg(test)]
        BEFORE_ANCHOR_OPEN.with(|hook| { if let Some(callback) = hook.borrow_mut().take() { callback(); } });
        let mut opened = directory(&self.anchor)?;
        #[cfg(unix)]
        ensure!(opened.identity()? == self.anchor_identity, "原生适配目录身份已变化，未执行写入");
        #[cfg(not(unix))]
        ensure!(crate::library::filesystem_identity(&self.anchor)? == self.anchor_identity, "原生适配目录身份已变化，未执行写入");
        for component in config.strip_prefix(&self.anchor)?.components() {
            let part = Path::new(component.as_os_str());
            opened.mkdir(part)?;
            opened = opened.child(part)?;
        }
        let name = Path::new(parent.file_name().context("缺少适配目录名称")?);
        opened.mkdir(name)?;
        let rules = opened.child(name)?;
        #[cfg(unix)]
        {
            ensure!(self.rules_identity.as_ref().is_none_or(|expected| rules.identity().is_ok_and(|actual| &actual == expected)), "原生规则目录身份已变化，未执行写入");
            opened.verify_location(config)?;
            rules.verify_location(parent)?;
        }
        #[cfg(not(unix))]
        ensure!(self.rules_identity.as_ref().is_none_or(|expected| crate::library::filesystem_identity(parent).is_ok_and(|actual| &actual == expected)), "原生规则目录身份已变化，未执行写入");
        Ok((rules, opened))
    }

    pub(crate) fn install(&mut self) -> Result<bool> {
        self.validate()?;
        if let Some(installation) = &self.source_installation {
            let (source, _) = self.source_guard.as_ref().context("缺少 Grok Hook 来源绑定")?;
            ensure!(installation.canonicalize().ok().as_ref() == Some(source), "Grok Hook 安装入口与技能源不一致，已保留");
            if self.installation_guard.is_none() {
                self.installation_guard = Some((installation.clone(), Some(crate::library::filesystem_identity(installation)?)));
            }
        }
        if !self.needs_install() { return Ok(false); }
        let result = (|| {
            if let Some((previous, _)) = &self.expected {
                // Detach may fail after its rename has committed. Save the
                // recovery bytes before starting it and handle both phases.
                self.rollback_body = Some(previous.clone());
                self.detach()?;
            }
            self.install_absent()
        })();
        match result {
            Ok(changed) => Ok(changed),
            Err(error) => {
                let restored = self.rollback_install();
                anyhow::bail!("原生适配发布失败：{error}；{}", if restored.is_ok() { "已恢复预览前状态" } else { "恢复受阻，已保留恢复记录" });
            }
        }
    }

    fn rollback_install(&mut self) -> Result<bool> {
        if let (Some(previous), Some((current, _))) = (&self.rollback_body, &self.expected) {
            if previous == current {
                // Detach failed before moving the old entry. Verify its CAS
                // and preserve its inode instead of detaching it a second time.
                self.validate()?;
                return Ok(false);
            }
        }
        let detached = self.detach()?;
        let Some(previous) = self.rollback_body.take() else { return Ok(detached); };
        let desired = std::mem::replace(&mut self.body, previous);
        let result = self.install_absent();
        let previous = std::mem::replace(&mut self.body, desired);
        if result.is_err() { self.rollback_body = Some(previous); }
        result
    }

    fn install_absent(&mut self) -> Result<bool> {
        self.validate()?;
        ensure!(self.expected.is_none(), "原生适配入口尚未移出，已保留");
        let (parent, config_dir) = self.parent()?;
        let config = self.path.parent().and_then(Path::parent).context("缺少配置目录")?;
        // Stage outside `rules`: a partial file must never become instructions.
        #[cfg(unix)]
        let temporary = tempfile::Builder::new().prefix(".pleat-rule-").make_in(config, |path| {
            config_dir.mkdir_exclusive(Path::new(path.file_name().unwrap())).map_err(std::io::Error::other)
        })?;
        #[cfg(unix)]
        let (staging, staging_path) = { let (opened, path) = temporary.into_parts(); (opened, path.keep()?) };
        #[cfg(not(unix))]
        let (staging, staging_path) = { let path = tempfile::Builder::new().prefix(".pleat-rule-").tempdir_in(config)?.keep(); (directory(&path)?, path) };
        #[cfg(unix)]
        permissions::private_directory(&staging)?;
        let mut file = staging.create_file(Path::new("instruction.md"), 0o600)?;
        file.write_all(&self.body)?;
        file.sync_all()?;
        let created_identity = crate::library::filesystem_identity(&staging_path.join("instruction.md"))?;
        #[cfg(unix)]
        { config_dir.verify_location(config)?; parent.verify_location(self.path.parent().unwrap())?; }
        #[cfg(any(target_os = "macos", target_os = "linux"))]
        staging.rename_to(Path::new("instruction.md"), &parent, Path::new(self.path.file_name().unwrap()))?;
        #[cfg(not(any(target_os = "macos", target_os = "linux")))]
        crate::package_fs::rename_exclusive(&staging_path.join("instruction.md"), &self.path)?;
        self.expected = Some((self.body.clone(), created_identity));
        let flushed = (|| -> Result<()> {
            #[cfg(test)]
            FAIL_AFTER_PUBLISH.with(|flag| if flag.replace(false) { anyhow::bail!("injected rule durability failure"); } else { Ok(()) })?;
            parent.sync()
        })();
        if let Err(error) = flushed {
            let cleanup = self.detach();
            anyhow::bail!("适配入口持久化失败：{error}；{}", if cleanup.is_ok() { "已移出加载目录".into() } else { format!("保留待恢复：{}", cleanup.unwrap_err()) });
        }
        Ok(true)
    }

    /// Retain the exact file outside native rule discovery for recovery.
    pub(crate) fn detach(&mut self) -> Result<bool> {
        self.validate()?;
        if self.expected.is_none() { return Ok(false); }
        let (parent, config_dir) = self.parent()?;
        let config = self.path.parent().and_then(Path::parent).context("缺少配置目录")?;
        #[cfg(unix)]
        let temporary = tempfile::Builder::new().prefix(".pleat-removed-rule-").make_in(config, |path| {
            config_dir.mkdir_exclusive(Path::new(path.file_name().unwrap())).map_err(std::io::Error::other)
        })?;
        #[cfg(unix)]
        let (recovery, path) = { let (opened, path) = temporary.into_parts(); (opened, path.keep()?) };
        #[cfg(not(unix))]
        let (recovery, path) = { let path = tempfile::Builder::new().prefix(".pleat-removed-rule-").tempdir_in(config)?.keep(); (directory(&path)?, path) };
        #[cfg(unix)]
        permissions::private_directory(&recovery)?;
        let mut note = recovery.create_file(Path::new("restore.json"), 0o600)?;
        note.write_all(&serde_json::to_vec(&serde_json::json!({"original": self.path, "entry":"instruction.md"}))?)?;
        note.sync_all()?;
        #[cfg(unix)]
        { config_dir.verify_location(config)?; recovery.verify_location(&path)?; parent.verify_location(self.path.parent().unwrap())?; }
        let name = Path::new(self.path.file_name().unwrap());
        #[cfg(any(target_os = "macos", target_os = "linux"))]
        parent.rename_to(name, &recovery, Path::new("instruction.md"))?;
        #[cfg(not(any(target_os = "macos", target_os = "linux")))]
        crate::package_fs::rename_exclusive(&self.path, &path.join("instruction.md"))?;
        if !snapshot(&path.join("instruction.md"), self.max_bytes).is_ok_and(|snapshot| snapshot == self.expected) {
            #[cfg(any(target_os = "macos", target_os = "linux"))]
            let restored = recovery.rename_to(Path::new("instruction.md"), &parent, name);
            #[cfg(not(any(target_os = "macos", target_os = "linux")))]
            let restored = crate::package_fs::rename_exclusive(&path.join("instruction.md"), &self.path);
            anyhow::bail!("原生适配文件在执行时变化；{}", if restored.is_ok() { "已恢复".into() } else { format!("保留于 {}", path.display()) });
        }
        self.expected = None;
        #[cfg(test)]
        BEFORE_DETACH_SYNC.with(|hook| {
            if let Some(callback) = hook.borrow_mut().take() { callback() } else { Ok(()) }
        })?;
        parent.sync()?;
        Ok(true)
    }
}

#[cfg(test)]
thread_local! {
    static BEFORE_ANCHOR_OPEN: std::cell::RefCell<Option<Box<dyn FnOnce()>>> = const { std::cell::RefCell::new(None) };
    static FAIL_AFTER_PUBLISH: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
    pub(crate) static BEFORE_DETACH_SYNC: std::cell::RefCell<Option<Box<dyn FnOnce() -> Result<()>>>> = const { std::cell::RefCell::new(None) };
}

#[cfg(test)]
mod tests {
    #[test]
    fn copilot_removal_preserves_all_entries_when_unselected_alias_is_redirected() {
        use super::*;
        let temp = tempfile::tempdir().unwrap();
        let project = temp.path().canonicalize().unwrap();
        let source = project.join("source");
        let other = project.join("other");
        for root in [&source, &other] {
            fs::create_dir_all(root.join("local-data")).unwrap();
            fs::write(root.join("local-data/ADAPTATION.md"), "KEEP_LOCAL").unwrap();
        }
        let shared = project.join(".agents/skills");
        fs::create_dir_all(&shared).unwrap();
        fs::create_dir_all(project.join(".github")).unwrap();
        std::os::unix::fs::symlink(&shared, project.join(".github/skills")).unwrap();
        std::os::unix::fs::symlink(&source, shared.join("demo")).unwrap();
        let selected = shared.join("demo");
        for path in [&selected, &project.join(".github/skills/demo")] {
            RulePlan::for_copilot(&project, path).unwrap().install().unwrap();
        }
        let instruction = project.join(".github/copilot-instructions.md");
        let before = fs::read(&instruction).unwrap();
        let mut plans = RulePlan::copilot_removals(&project, &selected).unwrap();
        let foreign = project.join("foreign-skills");
        fs::create_dir(&foreign).unwrap();
        std::os::unix::fs::symlink(&other, foreign.join("demo")).unwrap();
        fs::remove_file(project.join(".github/skills")).unwrap();
        std::os::unix::fs::symlink(&foreign, project.join(".github/skills")).unwrap();
        for plan in &mut plans {
            assert!(plan.validate().is_err());
            assert!(plan.detach().is_err());
        }
        assert_eq!(fs::read(&instruction).unwrap(), before);
        assert_eq!(selected.canonicalize().unwrap(), source);
        assert_eq!(foreign.join("demo").canonicalize().unwrap(), other);
        for root in [&source, &other] { assert_eq!(fs::read(root.join("local-data/ADAPTATION.md")).unwrap(), b"KEEP_LOCAL"); }
    }

    use super::*;
    #[test]
    fn imports_use_installed_links_and_conflicts_are_preserved() {
        let temp = tempfile::tempdir().unwrap();
        let root = temp.path().canonicalize().unwrap();
        let link = root.join(".claude/skills/含 空格");
        let mut plan = RulePlan::for_target(InstallTarget::ClaudeCode, &link).unwrap().unwrap();
        assert!(plan.install().unwrap());
        let body = fs::read_to_string(&plan.path).unwrap();
        assert!(body.contains("@../skills/含\\ 空格/local-data/ADAPTATION.md"));
        let mut existing = RulePlan::for_target(InstallTarget::ClaudeCode, &link).unwrap().unwrap();
        assert!(!existing.install().unwrap());
        fs::write(&plan.path, "user changes").unwrap();
        assert!(existing.detach().is_err());
        assert!(RulePlan::for_target(InstallTarget::ClaudeCode, &link).is_err());
        assert_eq!(fs::read_to_string(&plan.path).unwrap(), "user changes");
    }
    #[test]
    fn uninstall_retains_recovery_outside_rules_and_rejects_swapped_parent() {
        let temp = tempfile::tempdir().unwrap();
        let root = temp.path().canonicalize().unwrap();
        let link = root.join(".claude/skills/demo");
        let mut plan = RulePlan::for_target(InstallTarget::ClaudeCode, &link).unwrap().unwrap();
        plan.install().unwrap();
        let mut plan = RulePlan::for_target(InstallTarget::ClaudeCode, &link).unwrap().unwrap();
        assert!(plan.detach().unwrap());
        assert!(!plan.path.exists());
        assert_eq!(fs::read_dir(root.join(".claude/rules")).unwrap().count(), 0);
        assert!(fs::read_dir(root.join(".claude")).unwrap().flatten().any(|entry| entry.file_name().to_string_lossy().starts_with(".pleat-removed-rule-") && entry.path().join("instruction.md").is_file()));
        let mut stale = RulePlan::for_target(InstallTarget::ClaudeCode, &link).unwrap().unwrap();
        fs::rename(root.join(".claude/rules"), root.join(".claude/old-rules")).unwrap();
        fs::create_dir(root.join(".claude/rules")).unwrap();
        assert!(stale.install().is_err());
    }
    #[test]
    fn anchor_replacement_between_validation_and_open_never_receives_writes() {
        for existing_rules in [false, true] {
            let temp = tempfile::tempdir().unwrap();
            let root = temp.path().canonicalize().unwrap();
            fs::create_dir(root.join(".claude")).unwrap();
            if existing_rules { fs::create_dir(root.join(".claude/rules")).unwrap(); }
            let mut plan = RulePlan::for_target(InstallTarget::ClaudeCode, &root.join(".claude/skills/demo")).unwrap().unwrap();
            let replaced = root.join(if existing_rules { ".claude/rules" } else { ".claude" });
            let replacement = replaced.clone();
            BEFORE_ANCHOR_OPEN.with(|hook| *hook.borrow_mut() = Some(Box::new(move || {
                fs::rename(&replaced, replaced.with_extension("old")).unwrap();
                fs::create_dir(&replaced).unwrap();
            })));
            assert!(plan.install().is_err());
            assert_eq!(fs::read_dir(replacement).unwrap().count(), 0);
        }
    }
    #[test]
    fn publish_durability_failure_detaches_rule_and_can_retry() {
        let temp = tempfile::tempdir().unwrap(); let root = temp.path().canonicalize().unwrap();
        let mut plan = RulePlan::for_target(InstallTarget::ClaudeCode, &root.join(".claude/skills/demo")).unwrap().unwrap();
        FAIL_AFTER_PUBLISH.with(|flag| flag.set(true));
        assert!(plan.install().is_err());
        assert!(!plan.path.exists());
        assert!(plan.install().unwrap());
        assert!(plan.path.is_file());
    }
}
